function build(M) {
  const R = 1.4;
  const tyre = M.T(M.torus(1.3, 0.1, 64, 14), {rx: 90});
  const knobs = [];
  for (let i = 0; i < 48; i++) {
    const a = i / 48 * Math.PI * 2;
    knobs.push(M.T(M.box(0.06, 0.04, 0.16, -0.02), {pos: [Math.cos(a) * 1.38, Math.sin(a) * 1.38, 0], rz: a * 180 / Math.PI - 90}));
  }
  const rim = M.T(M.lathe([[1.16, -0.05], [1.2, -0.06], [1.2, 0.06], [1.16, 0.05], [1.14, 0]], 64), {rx: 90});
  const spokes = [];
  for (let i = 0; i < 32; i++) {
    const a = i / 32 * Math.PI * 2;
    const side = i % 2 ? 0.08 : -0.08;
    const a2 = a + (i % 4 < 2 ? 0.25 : -0.25);
    spokes.push(M.pipe([Math.cos(a2) * 0.07, Math.sin(a2) * 0.07, side], [Math.cos(a) * 1.15, Math.sin(a) * 1.15, side * 0.2], 0.008, 4));
  }
  const hub = M.T(M.lathe([[0.03, -0.11], [0.09, -0.1], [0.09, -0.07], [0.05, -0.05], [0.05, 0.05], [0.09, 0.07], [0.09, 0.1], [0.03, 0.11]], 24), {rx: 90});
  const axle = M.T(M.cyl(0.02, 0.25, 12, -0.125), {rx: 90});
  const lever = M.merge([
    M.T(M.cyl(0.035, 0.02, 16, 0), {rx: 90, pos: [0, 0, 0.125]}),
    M.pipe([0, 0, 0.13], [0.2, 0.05, 0.12], 0.015, 8)
  ]);
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge([tyre].concat(knobs))},
    {material: "steel", look: "solid", mesh: M.merge([rim, hub, axle].concat(spokes))},
    {material: "red", look: "solid", mesh: lever}
  ];
}

function build(M) {
  const R = 1.4, z = 0.125;
  const tyre = M.T(M.torus(1.3, 0.1, 48, 12), {rx: 90});
  const knobs = [];
  for (let i = 0; i < 48; i++) {
    const a = i * 7.5;
    knobs.push(M.T(M.box(0.06, 0.04, 0.16, 0), {pos: [Math.cos(a * Math.PI / 180) * 1.37, Math.sin(a * Math.PI / 180) * 1.37, 0], rz: a - 90}));
  }
  const rim = M.T(M.lathe([[1.16, -0.06], [1.22, -0.06], [1.22, 0.06], [1.16, 0.06], [1.16, -0.06]], 48), {rx: 90});
  const spokes = [];
  for (let i = 0; i < 32; i++) {
    const a = i * Math.PI * 2 / 32, side = i % 2 ? 0.07 : -0.07;
    spokes.push(M.pipe([0, 0, side], [Math.cos(a) * 1.16, Math.sin(a) * 1.16, 0], 0.008, 4));
  }
  const hub = M.T(M.cyl(0.07, 0.2, 24, -0.1), {rx: 90});
  const flanges = [M.T(M.cyl(0.12, 0.015, 24, 0.06), {rx: 90}), M.T(M.cyl(0.12, 0.015, 24, -0.075), {rx: 90})];
  const axle = M.T(M.cyl(0.025, 0.25, 12, -0.125), {rx: 90});
  const cogs = [];
  for (let k = 0; k < 4; k++) {
    const r = 0.26 - k * 0.04, n = Math.round(r * 110), pts = [];
    for (let i = 0; i < n * 2; i++) {
      const a = i * Math.PI / n, rr = i % 2 ? r : r - 0.025;
      pts.push([Math.cos(a) * rr, Math.sin(a) * rr]);
    }
    cogs.push(M.T(M.extrude(pts, 0.012), {rx: 90, pos: [0, 0, -0.08 - k * 0.012]}));
  }
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge([tyre, ...knobs])},
    {material: "steel", look: "solid", mesh: M.merge([rim, ...spokes, hub, ...flanges, axle])},
    {material: "gold", look: "solid", mesh: M.merge(cogs)}
  ];
}

function build(M) {
