  const headLow = [0.65, 0.6, 0];
  const seat = M.pipe(bb, seatTop, r, 28);
  const down = M.pipe(bb, headLow, r * 1.15, 28);
  const shell = M.T(M.cyl(0.09, 0.22, 32, -0.11), {pos: bb, rx: 90});
  const weld1 = M.T(M.sphere(0.075, 20, 12), {pos: [-0.42, -0.6, 0]});
