  const headStub = M.T(M.cyl(0.075, 0.12, 28, -0.06), {pos: headLow, rz: 40});
  const ang = Math.atan2(1.3, 1.05) * 180 / Math.PI;
  const mid = (t) => [bb[0] + 1.05 * t, bb[1] + 1.3 * t, 0];
  const sticker = M.T(M.box(0.3, 0.012, 0.11, 0), {pos: mid(0.62), rz: ang - 90 + 180, ry: 0});
  const stk = M.T(M.box(0.012, 0.28, 0.08, 0), {pos: [mid(0.62)[0], mid(0.62)[1] - 0.14, 0.055], rz: -(90 - ang)});
  const cage = [];
  const cp = mid(0.35);
  const rot = -(90 - ang);
  cage.push(M.T(M.box(0.06, 0.32, 0.01, -0.16), {pos: [cp[0] + 0.06, cp[1], 0], rz: rot}));
  cage.push(M.T(M.tube(0.06, 0.3, 20), {pos: [cp[0] + 0.12, cp[1] - 0.05, 0], rz: rot, s: [1, 1, 0.8]}));
  const screws = [];
  for (const t of [0.28, 0.42]) {
    const p = mid(t);
