  return [
    {material: "red", look: "solid", mesh: M.merge([seat, down, weld1, weld2, collar, headStub])},
    {material: "dark_steel", look: "solid", mesh: M.merge([shell, ...cage])},
    {material: "steel", look: "solid", mesh: M.merge(screws)},
    {material: "white", look: "solid", mesh: M.merge([stk])}
  ];
}

