  for (let i = 0; i < 6; i++) dark.push(M.torus(0.026, 0.004, 24, 6), M.T(M.torus(0.026, 0.004, 24, 6), {pos: [0, 0.12 + i * 0.018, 0]}));
  dark.push(M.T(M.cyl(0.04, 0.03, 6, 0), {pos: [0, 0.2, 0]}));
  dark.push(M.T(M.cyl(0.035, 0.02, 6, 0), {pos: [0, -0.25, 0]}));
  const balls = [];
  for (const y of [0.17, -0.2]) {
    balls.push(M.T(M.torus(0.045, 0.006, 32, 8), {pos: [0, y - 0.012, 0]}));
    balls.push(M.T(M.torus(0.045, 0.006, 32, 8), {pos: [0, y + 0.012, 0]}));
    for (let k = 0; k < 12; k++) {
