    {material: "steel", look: "solid", mesh: t(M.merge(steel))},
    {material: "dark_steel", look: "solid", mesh: t(M.merge(dark))},
    {material: "gold", look: "solid", mesh: t(M.merge(balls))}
  ];
}

function build(M) {
  const red = [], steel = [], dark = [];
  const zs = [-0.04, 0.04];
  // fork crown at top
  red.push(M.box(0.16, 0.08, 0.1, 0.72, -0.1));
  steel.push(M.cyl(0.035, 0.18, 24, 0.8));
  steel.push(M.T(M.cyl(0.035, 0.18, 24, 0), {pos: [-0.1, 0.8, 0]}));
  for (const z of zs) {
    // blade: segments leaning, then curving forward
    const pts = [];
    for (let i = 0; i <= 10; i++) {
      const t = i / 10;
      const y = 0.74 - t * 1.55;
      const x = -0.12 + 0.08 * t + 0.16 * Math.pow(t, 3);
      pts.push([x, y, z]);
    }
    for (let i = 0; i < 10; i++) {
      const r = 0.018 - i * 0.0008;
      red.push(M.pipe(pts[i], pts[i + 1], r, 16));
      red.push(M.T(M.sphere(r, 12, 8), {pos: pts[i + 1]}));
    }
    // dropout
    const e = pts[10];
    dark.push(M.T(M.box(0.07, 0.06, 0.012, 0, 0), {pos: [e[0] + 0.02, e[1] - 0.06, z]}));
    steel.push(M.T(M.cyl(0.012, 0.02, 16, -0.01), {pos: [e[0] + 0.04, e[1] - 0.045, z], rx: 90}));
  }
  return [
    {material: "red", look: "solid", mesh: M.merge(red)},
    {material: "steel", look: "solid", mesh: M.merge(steel)},
    {material: "dark_steel", look: "solid", mesh: M.merge(dark)}
  ];
}

function build(M) {
  const bar = M.pipe([0, 0.12, -0.72], [0, 0.12, 0.72], 0.035, 24);
  const bendL = M.pipe([0, 0.12, -0.72], [-0.08, 0.12, -0.98], 0.035, 24);
  const bendR = M.pipe([0, 0.12, 0.72], [-0.08, 0.12, 0.98], 0.035, 24);
  const clamp = M.T(M.cyl(0.06, 0.16, 24, -0.08), {pos: [0, 0.12, 0], rx: 90});
  const stem = M.pipe([-0.16, 0.02, 0], [0, 0.12, 0], 0.04, 24);
  const stemCap = M.T(M.cyl(0.05, 0.08, 24, 0), {pos: [-0.16, -0.06, 0]});
  const metal = M.merge([bar, bendL, bendR, clamp, stem, stemCap]);
  const bolts = [];
  for (const z of [-0.05, 0.05]) bolts.push(M.T(M.cyl(0.015, 0.03, 12, 0), {pos: [0.055, 0.12, z], rz: -90}));
  const gripL = M.T(M.cyl(0.05, 0.22, 24, -0.11), {pos: [-0.06, 0.12, -0.88], rx: 90, ry: -17});
  const gripR = M.T(M.cyl(0.05, 0.22, 24, -0.11), {pos: [-0.06, 0.12, 0.88], rx: 90, ry: 17});
  const levers = [], cables = [];
  for (const s of [-1, 1]) {
    levers.push(M.T(M.box(0.04, 0.03, 0.06, -0.015), {pos: [0.03, 0.12, s * 0.7]}));
    levers.push(M.pipe([0.05, 0.12, s * 0.7], [0.18, 0.06, s * 0.82], 0.012, 12));
    cables.push(M.pipe([0.02, 0.14, s * 0.68], [-0.1, 0.18, s * 0.4], 0.008, 8));
    cables.push(M.pipe([-0.1, 0.18, s * 0.4], [-0.18, 0.0, s * 0.1], 0.008, 8));
  }
  return [
    {material: "steel", look: "solid", mesh: metal},
    {material: "dark_steel", look: "solid", mesh: M.merge([...bolts, gripL, gripR])},
    {material: "red", look: "solid", mesh: M.merge(levers)},
    {material: "dark_steel", look: "solid", mesh: M.merge(cables)}
  ];
}

function build(M) {
  const R = 0.3, th = 0.03;
  const out = [];
  const N = 40;
  for (let i = 0; i < N; i++) {
    const a0 = (i / N) * Math.PI * 2, a1 = ((i + 0.5) / N) * Math.PI * 2, a2 = ((i + 1) / N) * Math.PI * 2;
    out.push([Math.cos(a0) * R, Math.sin(a0) * R], [Math.cos(a1) * (R + 0.03), Math.sin(a1) * (R + 0.03)]);
  }
  const ring = M.T(M.extrude(out, th), { rx: 90, pos: [0, 0, 0.06] });
  const hole = M.T(M.torus(0.2, 0.012, 40, 8), { rx: 90, pos: [0, 0, 0.08] });
  const bolts = [];
  for (let i = 0; i < 5; i++) {
    const a = i / 5 * Math.PI * 2;
    bolts.push(M.T(M.cyl(0.018, 0.02, 16, 0), { rx: 90, pos: [Math.cos(a) * 0.17, Math.sin(a) * 0.17, 0.085] }));
  }
  bolts.push(M.T(M.cyl(0.05, 0.2, 24, -0.1), { rx: 90 }));
  const L = 0.32, ca = 70 * Math.PI / 180;
  const cx = Math.cos(ca) * L, cy = Math.sin(ca) * L;
  const arms = M.merge([
    M.pipe([0, 0, 0.1], [cx, cy, 0.1], 0.025, 16),
    M.pipe([0, 0, -0.1], [-cx, -cy, -0.1], 0.025, 16),
    M.pipe([cx, cy, 0.1], [cx, cy, 0.14], 0.012, 12),
    M.pipe([-cx, -cy, -0.1], [-cx, -cy, -0.14], 0.012, 12)
  ]);
  const pedals = [], studs = [];
  [[cx, cy, 0.19], [-cx, -cy, -0.19]].forEach(p => {
    pedals.push(M.box(0.18, 0.025, 0.1, p[1] - 0.0125, p[0]));
    pedals[pedals.length - 1] = M.T(pedals[pedals.length - 1], { pos: [0, 0, p[2]] });
    for (let i = -1; i <= 1; i += 2) for (let j = -1; j <= 1; j += 2)
      studs.push(M.T(M.cyl(0.008, 0.015, 8, 0), { pos: [p[0] + i * 0.07, p[1] + 0.0125, p[2] + j * 0.035] }));
  });
  const links = [];
  const top = R + 0.01;
  for (let k = 0; k < 9; k++) {
    const x = -0.05 - k * 0.05;
    links.push(M.box(0.045, 0.02, 0.02, top - 0.01, x));
    links.push(M.box(0.045, 0.02, 0.02, -top - 0.01, x));
  }
  for (let k = 0; k < 10; k++) {
    const a = Math.PI / 2 + k / 9 * Math.PI;
    links.push(M.T(M.box(0.045, 0.02, 0.02, -0.01), { pos: [0, 0, 0], rz: 0 }));
    links[links.length - 1] = M.T(M.box(0.02, 0.045, 0.02, -0.0225), { pos: [-0.5 + Math.cos(a) * top * 0.4 + 0.12, Math.sin(a) * top, 0] });
  }
  const chain = M.T(M.merge(links), { pos: [0, 0, 0.06] });
  return [
    { material: "steel", look: "solid", mesh: M.merge([ring, hole]) },
    { material: "dark_steel", look: "solid", mesh: M.merge([arms, M.merge(pedals)]) },
    { material: "gold", look: "solid", mesh: M.merge(bolts) },
    { material: "steel", look: "solid", mesh: M.merge(studs) },
    { material: "dark_steel", look: "solid", mesh: chain }
  ];
}

function build(M) {
  const outline = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24, x = -0.5 + t;
    const w = 0.25 * (t < 0.35 ? Math.sqrt(Math.sin((t / 0.35) * Math.PI / 2) * 0.9 + 0.1) : (1 - (t - 0.35) / 0.65 * 0.75));
    outline.push([x, w]);
  }
  for (let i = 24; i >= 0; i--) outline.push([outline[i][0], -outline[i][1]]);
  const pad = M.T(M.extrude(outline, 0.08), {pos: [0, 0.24, 0]});
  const shell = M.T(M.extrude(outline, 0.03), {pos: [0, 0.185, 0], s: [0.97, 1, 0.95]});
  const nose = M.T(M.sphere(0.05, 16, 8, Math.PI / 2), {pos: [0.44, 0.2, 0], s: [1.2, 0.8, 1]});
  const rails = [];
  for (const z of [-0.07, 0.07]) {
    rails.push(M.pipe([-0.3, 0.17, z * 1.6], [-0.2, 0.12, z], 0.012, 12));
    rails.push(M.pipe([-0.2, 0.12, z], [0.25, 0.12, z * 0.6], 0.012, 12));
    rails.push(M.pipe([0.25, 0.12, z * 0.6], [0.38, 0.17, 0], 0.012, 12));
  }
  const post = M.cyl(0.035, 0.1, 24, 0);
  const clamp = M.box(0.12, 0.04, 0.18, 0.09);
  const bolt = M.T(M.cyl(0.018, 0.22, 16, -0.11), {pos: [0, 0.11, 0], rx: 90});
  const label = M.T(M.box(0.12, 0.005, 0.06, 0.32), {pos: [-0.3, 0, 0]});
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge([pad, shell, nose])},
    {material: "steel", look: "solid", mesh: M.merge([...rails, post, bolt])},
    {material: "dark_steel", look: "solid", mesh: clamp},
    {material: "red", look: "solid", mesh: label}
  ];
}
